const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fold = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const euros = value => Number.isFinite(value) ? new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(value/100) : '—';
const priceInput = value => Number.isFinite(value) ? (value/100).toFixed(2).replace('.',',') : '';
const date = value => value ? new Intl.DateTimeFormat('pt-PT',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(value.length===10 ? value+'T12:00:00' : value)) : '—';
const timestamp = value => value ? new Intl.DateTimeFormat('pt-PT',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value)) : '—';
function today(){const n=new Date();return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;}
