const can = permission => workspace?.permissions?.includes(permission);
const manager = () => workspace?.user?.role==='gerente';
const allowedTab = def => !def.permissions.length || def.permissions.some(can) || (def===moduleDefs.approvals&&manager());
function notify(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
function showAuth(){workspace=null;csrfToken='';dialogSubmit=null;$('record-dialog').close();$('job-detail-dialog').close();$('job-detail-body').replaceChildren();$('record-form').reset();$('dialog-fields').replaceChildren();$('dialog-title').textContent='';$('dialog-reference').textContent='';$('dialog-hint').textContent='';$('form-error').hidden=true;$('application').hidden=true;$('auth-screen').hidden=false;$('module-content').replaceChildren();$('module-nav').replaceChildren();$('metrics').replaceChildren();$('module-actions').replaceChildren();$('customer-filter').replaceChildren(new Option('Todos os clientes',''));$('status-filter').replaceChildren(new Option('Todos os estados',''));$('user-name').textContent='';$('user-role').textContent='';clearTimeout(toastTimer);$('toast').hidden=true;$('auth-password').value='';$('auth-form').hidden=false;$('auth-title').textContent=setupRequired?'Criar acesso do gerente':'Entrar na TSS Gestão';$('auth-description').textContent=setupRequired?'Defina a primeira conta de Sergiu Sandu. A palavra-passe será escolhida por si.':'Use a sua conta individual para aceder às funções autorizadas.';$('setup-name-field').hidden=!setupRequired;$('password-hint').hidden=!setupRequired;$('auth-password').minLength=setupRequired?12:1;$('auth-password').autocomplete=setupRequired?'new-password':'current-password';$('auth-submit').textContent=setupRequired?'Criar conta e entrar':'Entrar';if(setupRequired&&!$('auth-username').value)$('auth-username').value='sergiu.sandu';}
async function api(path,method='GET',body){
  let response;
  try{response=await fetch(path,{method,headers:{'Content-Type':'application/json','X-TSS-Request':'1',...(csrfToken?{'X-CSRF-Token':csrfToken}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});}
  catch{throw new Error('Não foi possível ligar à aplicação. Verifique se está em execução.');}
  const result=await response.json().catch(()=>({error:'Resposta inválida da aplicação.'}));
  if(!response.ok){if(response.status===401&&workspace){setupRequired=false;showAuth();}throw new Error(result.error||'Não foi possível concluir a operação.');}
  if(result.csrfToken)csrfToken=result.csrfToken;
  return result;
}
async function loadSession(){
  try{const session=await api('/api/session');setupRequired=!!session.setupRequired;$('auth-retry').hidden=true;$('auth-error').hidden=true;if(session.user){csrfToken=session.csrfToken;await refresh();}else showAuth();}
  catch(error){$('auth-title').textContent='Ligação indisponível';$('auth-description').textContent=error.message;$('auth-retry').hidden=false;}
}
async function refresh(){
  const state=await api('/api/workspace');workspace=state;
  if(state.csrfToken)csrfToken=state.csrfToken;
for(const key of ['jobs','customers','quotes','yard','workOrders','invoices','approvals','audit','users','roles','staff','vehicles','drivers','opportunities','activities','costs','incidents','attachments','contributions'])workspace[key]??=[];
  if(!allowedTab(moduleDefs[currentTab]))currentTab=Object.keys(moduleDefs).find(key=>allowedTab(moduleDefs[key]));
  $('auth-screen').hidden=true;$('application').hidden=false;$('workspace-error').hidden=true;
  $('user-name').textContent=workspace.user.name;$('user-role').textContent=workspace.roles.find(role=>role.id===workspace.user.role)?.label||workspace.user.role;
  $('user-initials').textContent=workspace.user.name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
  renderWorkspace();$('saved-label').textContent='Atualizado às '+new Intl.DateTimeFormat('pt-PT',{hour:'2-digit',minute:'2-digit'}).format(new Date());
}
$('auth-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;busy=true;$('auth-submit').disabled=true;$('auth-error').hidden=true;try{const result=await api(setupRequired?'/api/setup':'/api/login','POST',{username:$('auth-username').value.trim(),password:$('auth-password').value,...(setupRequired?{name:$('auth-name').value.trim()}: {})});csrfToken=result.csrfToken;$('auth-password').value='';await refresh();}catch(error){$('auth-error').textContent=error.message;$('auth-error').hidden=false;}finally{busy=false;$('auth-submit').disabled=false;}});
