function button(label,command,type='',id='',style='secondary',disabled=false){return `<button type="button" class="button ${style} small" data-command="${esc(command)}" data-type="${esc(type)}" data-id="${esc(id)}" ${disabled?'disabled':''}>${esc(label)}</button>`;}
function pill(status){const key=fold(status).replace(/[^a-z]/g,'');return `<span class="workflow-pill state-${key}">${esc(status)}</span>`;}
function detail(label,value){return `<div><dt>${esc(label)}</dt><dd>${esc(value??'—')}</dd></div>`;}
function card(title,reference,status,details,actions='',extra=''){return `<article class="entity-card"><div class="entity-head"><div><h3>${esc(title)}</h3><p>${esc(reference)}</p></div>${pill(status)}</div>${extra}<dl class="entity-details">${details}</dl>${actions?`<div class="entity-actions">${actions}</div>`:''}</article>`;}
function empty(text){return `<div class="suite-empty"><h3>Nenhum registo</h3><p>${esc(text)}</p></div>`;}
function paid(invoice){return (invoice.payments||[]).reduce((sum,p)=>sum+p.amountCents,0);}
function jobPayment(job){return job.paymentStatus||'';}
function filtered(items,ignoreStatus=false){const terms=fold($('search').value).trim().split(/\s+/).filter(Boolean),status=ignoreStatus?'':$('status-filter').value;return items.filter(item=>terms.every(term=>fold(JSON.stringify(item)).includes(term))&&(!status||entityStatus(item)===status));}
function entityStatus(item){if(currentTab==='yard')return item.checkedOutAt?'Saiu':'No parque';if(currentTab==='users')return item.active?'Ativo':'Inativo';return item.status||'';}
function currentRecords(){return ({crm:workspace.quotes,tms:workspace.jobs,planning:workspace.jobs,fleet:workspace.vehicles,drivers:workspace.drivers,sales:workspace.opportunities,costs:workspace.costs,incidents:workspace.incidents,yard:workspace.yard,workshop:workspace.workOrders,finance:workspace.invoices,approvals:workspace.approvals,users:workspace.users,audit:workspace.audit})[currentTab]||[];}
