  const selected=$('status-filter').value;$('status-filter').replaceChildren(new Option('Todos os estados',''));[...new Set(currentRecords().map(entityStatus).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-PT')).forEach(status=>$('status-filter').add(new Option(status,status)));if([...$('status-filter').options].some(o=>o.value===selected))$('status-filter').value=selected;
