  let records=filtered(currentRecords());
  if(currentTab==='tms'){const payment=$('payment-filter').value,customer=$('customer-filter').value,from=$('date-from').value,to=$('date-to').value;records=records.filter(j=>(!payment||jobPayment(j)===payment)&&(!customer||j.customer===customer)&&(!from||j.pickupDate>=from)&&(!to||j.pickupDate<=to)).sort((a,b)=>a.pickupDate.localeCompare(b.pickupDate));}
