    fleet:[metric('Viaturas',workspace.vehicles.length,'Frota registada'),metric('Disponíveis',workspace.vehicles.filter(v=>v.status==='Disponível').length,'Sujeitas aos controlos da expedição'),metric('Indisponíveis',workspace.vehicles.filter(v=>v.status==='Indisponível').length,'Rever situação operacional'),metric('Alertas',workspace.vehicles.reduce((count,v)=>count+vehicleAlerts(v).length,0),'Prazos e manutenção')],
    drivers:[metric('Perfis',workspace.drivers.length,'Motoristas registados'),metric('Ativos',workspace.drivers.filter(d=>d.status==='Ativo').length,'Habilitações a confirmar'),metric('Com acesso',workspace.drivers.filter(d=>d.userId).length,'Conta individual associada'),metric('Suspensos',workspace.drivers.filter(d=>d.status==='Suspenso').length,'Não afetar novos serviços')],
    sales:[metric('Oportunidades abertas',workspace.opportunities.filter(o=>!['Ganho','Perdido'].includes(o.status)).length,'Carteira comercial em acompanhamento'),metric('Valor em aberto',euros(workspace.opportunities.filter(o=>!['Ganho','Perdido'].includes(o.status)).reduce((sum,o)=>sum+(o.expectedValueCents||0),0)),'Estimativa comercial'),metric('Seguimentos devidos',workspace.opportunities.filter(o=>o.nextFollowUpDate&&o.nextFollowUpDate<=today()&&!['Ganho','Perdido'].includes(o.status)).length,'Até ao dia de hoje'),metric('Atividades',workspace.activities.length,'Contactos e tarefas registados')],
    incidents:[metric('Abertas',workspace.incidents.filter(i=>i.status==='Aberta').length,'Ainda por analisar'),metric('Em análise',workspace.incidents.filter(i=>i.status==='Em análise').length,'Tratamento em curso'),metric('Prioridade alta',workspace.incidents.filter(i=>i.severity==='high'&&i.status!=='Resolvida').length,'Acompanhar com prioridade'),metric('Resolvidas',workspace.incidents.filter(i=>i.status==='Resolvida').length,'Com resolução registada')],
