    crm:[metric('Clientes',workspace.customers.length,'Carteira de clientes'),metric('Propostas',workspace.quotes.length,'Histórico comercial'),metric('A aguardar decisão',workspace.quotes.filter(q=>q.status==='Em aprovação').length,'Aprovação do gerente'),metric('Aprovadas / aceites',activeQuotes,'Prontas para o passo seguinte')],
    tms:[metric('Serviços apresentados',records.length,'Filtros aplicados à lista'),metric('Em curso',activeJobs,'Transportes em execução'),metric(availableMoney?'Valor acordado':'Concluídos',availableMoney?euros(records.filter(j=>j.status!=='Cancelado').reduce((s,j)=>s+j.priceCents,0)):records.filter(j=>j.status==='Concluído').length,availableMoney?'Sem serviços cancelados':'Com entrega registada'),metric('Sem afetação',records.filter(j=>!j.vehicle||!j.driver).length,'Atribuir motorista e viatura')],
    yard:[metric('No parque',workspace.yard.filter(y=>!y.checkedOutAt).length,'Entradas por concluir'),metric('Movimentos',workspace.yard.reduce((n,y)=>n+(y.movements?.length||0),0),'Entrada, mudança e saída'),metric('Saídas',workspace.yard.filter(y=>y.checkedOutAt).length,'Histórico preservado'),metric('Localizações ocupadas',new Set(workspace.yard.filter(y=>!y.checkedOutAt).map(y=>y.location)).size,'Posição atual das viaturas')],
