    audit:[metric('Eventos',workspace.audit.length,'Histórico devolvido pelo servidor'),metric('Autoria','Identificada','Nome, função e data'),metric('Aprovações','Registadas','Incluem justificações'),metric('Exportação','Controlada','Acesso por função')],
